import { MeshStandardNodeMaterial, PlaneGeometry, Mesh, Group, Vector2 } from 'three/webgpu';
import { texture, uv, uniform, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // ----- geometry -----
  const width = 1;
  const height = 0.625; // 320/512 aspect ratio
  const segments = 64;
  const geo = new PlaneGeometry(width, height, segments, segments);

  // ----- node material with displacement and parallax -----
  const colorMap = uniform(null);
  const displacementMap = uniform(null);
  const parallaxOffset = uniform(new Vector2(0, 0));

  const offsetUv = add(uv(), parallaxOffset);
  const dispNode = mul(texture(displacementMap, offsetUv).r, uniform(0.05)); // 0.05 scene units

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(colorMap, uv());
  material.displacementNode = dispNode;
  material.side = 2; // DoubleSide
  material.metalness = 0.55;
  material.roughness = 0.5;

  // ----- mesh -----
  const mesh = new Mesh(geo, material);
  mesh.position.set(0, 0, 0);
  mesh.name = 'ornamental-divider';
  group.add(mesh);

  // store original Y for rise-in effect
  const originalY = mesh.position.y;
  const originalScale = mesh.scale.clone();

  // ----- load textures -----
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorMap.value = tex;
    material.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    displacementMap.value = tex;
    material.needsUpdate = true;
  });

  // ----- interactions (hover lift, click press-down, emit) -----
  group.userData.handlers = {
    onPointerEnter: () => {
      gsap.to(mesh.position, {
        y: originalY + 0.15,
        duration: 0.5,
        ease: 'power3.out'
      });
    },
    onPointerLeave: () => {
      gsap.to(mesh.position, {
        y: originalY,
        duration: 0.5,
        ease: 'power3.out'
      });
    },
    onPointerDown: () => {
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      });
    },
    onPointerUp: () => {
      gsap.to(mesh.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out'
      });
    },
    onClick: () => {
      ctx.emit('hub-features.select', {});
    },
    onPointerMove: (event) => {
      // subtle parallax – map mouse position to UV offset
      const dx = ((event.clientX / window.innerWidth) - 0.5) * 0.02;
      const dy = ((event.clientY / window.innerHeight) - 0.5) * 0.02;
      parallaxOffset.value.set(dx, dy);
    }
  };

  // ----- cleanup -----
  group.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);

    if (material) {
      colorMap.value?.dispose();
      displacementMap.value?.dispose();
      material.dispose();
    }
    geo.dispose();
  };

  return group;
}
